function parseGeneratedReviewPrompt(text: string): { mode: ReviewMode; prNumber: number } | undefined {
	const match = text.trim().match(/^(Review|Rereview) GitCode merge request #(\d+), but review ONLY the last commit\./);
	if (!match) {
		return undefined;
	}

	return {
		mode: match[1] === "Rereview" ? "rereview" : "review",
		prNumber: Number(match[2]),
	};
}

function truncateAutoNotes(text: string): string {
	const trimmed = text.trim();
	if (trimmed.length <= MAX_AUTO_REREVIEW_NOTES_CHARS) {
		return trimmed;
	}

	return `${trimmed.slice(0, MAX_AUTO_REREVIEW_NOTES_CHARS)}\n\n[Truncated to ${MAX_AUTO_REREVIEW_NOTES_CHARS} characters by ${EXTENSION_TYPE}.]`;
}

function findLatestAssistantReviewOutput(ctx: any, prNumber: number): string | undefined {
	const branch = ctx.sessionManager.getBranch();

	for (let promptIndex = branch.length - 1; promptIndex >= 0; promptIndex--) {
		const promptText = getMessageText(branch[promptIndex], "user");
		const prompt = parseGeneratedReviewPrompt(promptText);
		if (!prompt || prompt.prNumber !== prNumber) {
			continue;
		}

		let endIndex = branch.length;
		for (let index = promptIndex + 1; index < branch.length; index++) {
			if (getMessageText(branch[index], "user")) {
				endIndex = index;
				break;
			}
		}

		for (let index = endIndex - 1; index > promptIndex; index--) {
			const text = getMessageText(branch[index], "assistant");
			if (text) {
				return truncateAutoNotes(text);
			}
		}
	}

	return undefined;
}

function findLatestStoredReviewOutput(ctx: any, prNumber: number): string | undefined {
	const branch = ctx.sessionManager.getBranch();
	for (let index = branch.length - 1; index >= 0; index--) {
		const entry = branch[index] as { type?: unknown; customType?: unknown; data?: any };
		if (entry.type !== "custom" || entry.customType !== EXTENSION_TYPE) {
			continue;
		}

		if (entry.data?.kind !== "review-output" || entry.data?.prNumber !== prNumber) {
			continue;
		}

		if (typeof entry.data.output === "string" && entry.data.output.trim()) {
			return truncateAutoNotes(entry.data.output);
		}
	}

	return undefined;
}

function findAutoRereviewNotes(ctx: any, prNumber: number): string | undefined {
	return findLatestStoredReviewOutput(ctx, prNumber) ?? findLatestAssistantReviewOutput(ctx, prNumber);
}

